CREATE TABLE platform_spaces (space_id TEXT PRIMARY KEY NOT NULL) STRICT;
CREATE TABLE platform_users (
  user_id TEXT PRIMARY KEY NOT NULL, active INTEGER NOT NULL CHECK (active IN (0, 1))
) STRICT;
CREATE TABLE platform_credentials (
  username TEXT PRIMARY KEY NOT NULL, user_id TEXT NOT NULL UNIQUE REFERENCES platform_users,
  salt TEXT NOT NULL, password_hash TEXT NOT NULL
) STRICT;
CREATE TABLE platform_members (
  member_id TEXT PRIMARY KEY NOT NULL,
  user_id TEXT NOT NULL REFERENCES platform_users,
  space_id TEXT NOT NULL REFERENCES platform_spaces,
  active INTEGER NOT NULL CHECK (active IN (0, 1)),
  UNIQUE (space_id, user_id)
) STRICT;
CREATE TABLE platform_member_roles (
  member_id TEXT NOT NULL REFERENCES platform_members,
  role TEXT NOT NULL CHECK (role IN ('viewer', 'editor', 'publisher', 'admin')),
  PRIMARY KEY (member_id, role)
) STRICT;
CREATE TABLE platform_sessions (
  token_hash TEXT PRIMARY KEY NOT NULL,
  user_id TEXT NOT NULL REFERENCES platform_users,
  source TEXT NOT NULL,
  expires_at INTEGER NOT NULL,
  revoked_at INTEGER
) STRICT;
CREATE TABLE platform_forms (
  form_id TEXT PRIMARY KEY NOT NULL,
  space_id TEXT NOT NULL REFERENCES platform_spaces,
  name TEXT NOT NULL,
  created_by TEXT NOT NULL REFERENCES platform_users,
  created_at TEXT NOT NULL,
  archived INTEGER NOT NULL DEFAULT 0 CHECK (archived IN (0, 1))
) STRICT;
CREATE INDEX platform_forms_by_space ON platform_forms (space_id, name, form_id);
CREATE TABLE platform_versions (
  sequence INTEGER PRIMARY KEY,
  version_id TEXT NOT NULL UNIQUE,
  form_id TEXT NOT NULL REFERENCES platform_forms,
  text BLOB NOT NULL,
  saved_by TEXT NOT NULL REFERENCES platform_users,
  saved_at TEXT NOT NULL,
  based_on_version_id TEXT,
  UNIQUE (form_id, version_id),
  FOREIGN KEY (form_id, based_on_version_id) REFERENCES platform_versions (form_id, version_id)
) STRICT;
CREATE INDEX platform_versions_by_form ON platform_versions (form_id, sequence DESC);
CREATE TABLE platform_receipts (
  space_id TEXT NOT NULL REFERENCES platform_spaces,
  user_id TEXT NOT NULL REFERENCES platform_users,
  operation TEXT NOT NULL,
  request_key TEXT NOT NULL,
  fingerprint TEXT NOT NULL,
  result_id TEXT NOT NULL,
  PRIMARY KEY (space_id, user_id, operation, request_key)
) STRICT;

ALTER TABLE platform_forms ADD COLUMN description TEXT NOT NULL DEFAULT '';
ALTER TABLE platform_forms ADD COLUMN metadata_revision INTEGER NOT NULL DEFAULT 0;
ALTER TABLE platform_versions ADD COLUMN copied_from_version_id TEXT REFERENCES platform_versions(version_id);
ALTER TABLE platform_versions ADD COLUMN note TEXT;
CREATE TABLE platform_form_audit (
  sequence INTEGER PRIMARY KEY,
  form_id TEXT NOT NULL REFERENCES platform_forms,
  actor_id TEXT NOT NULL REFERENCES platform_users,
  action TEXT NOT NULL CHECK (action IN ('archive', 'restore')),
  recorded_at TEXT NOT NULL
) STRICT;

CREATE TABLE platform_github_bindings (
  sequence INTEGER PRIMARY KEY AUTOINCREMENT,
  user_id TEXT NOT NULL REFERENCES platform_users,
  github_id TEXT NOT NULL,
  github_login TEXT NOT NULL,
  revoked_at INTEGER
) STRICT;
CREATE UNIQUE INDEX platform_github_active_user
  ON platform_github_bindings (user_id) WHERE revoked_at IS NULL;
CREATE UNIQUE INDEX platform_github_active_identity
  ON platform_github_bindings (github_id) WHERE revoked_at IS NULL;
CREATE TABLE platform_github_flows (
  state_hash TEXT PRIMARY KEY NOT NULL,
  browser_hash TEXT NOT NULL,
  user_id TEXT REFERENCES platform_users,
  verifier TEXT NOT NULL,
  binding_sequence INTEGER NOT NULL,
  expires_at INTEGER NOT NULL,
  consumed INTEGER NOT NULL DEFAULT 0 CHECK (consumed IN (0, 1))
) STRICT;
CREATE INDEX platform_github_flows_browser ON platform_github_flows (browser_hash);

CREATE TABLE platform_member_changes (
    sequence INTEGER PRIMARY KEY AUTOINCREMENT,
    member_id TEXT NOT NULL REFERENCES platform_members,
    actor_id TEXT NOT NULL REFERENCES platform_users,
    state TEXT NOT NULL, recorded_at TEXT NOT NULL
  ) STRICT;

ALTER TABLE platform_github_flows ADD COLUMN started_at INTEGER NOT NULL DEFAULT 0;
   CREATE TABLE platform_github_registrations (
     browser_hash TEXT PRIMARY KEY NOT NULL,
     github_id TEXT NOT NULL,
     github_login TEXT NOT NULL,
     history_sequence INTEGER NOT NULL,
     history_revoked_at INTEGER,
     expires_at INTEGER NOT NULL
   ) STRICT;
   CREATE TABLE platform_account_changes (
     sequence INTEGER PRIMARY KEY AUTOINCREMENT,
     user_id TEXT NOT NULL REFERENCES platform_users,
     actor_id TEXT NOT NULL REFERENCES platform_users,
     state TEXT NOT NULL, recorded_at TEXT NOT NULL
   ) STRICT;

ALTER TABLE platform_github_flows ADD COLUMN purpose TEXT NOT NULL DEFAULT 'login';
   UPDATE platform_github_flows SET purpose='bind' WHERE user_id IS NOT NULL;
   CREATE TABLE platform_password_setup_proofs (
     browser_hash TEXT PRIMARY KEY NOT NULL,
     proof_id TEXT NOT NULL UNIQUE,
     user_id TEXT NOT NULL REFERENCES platform_users,
     binding_sequence INTEGER NOT NULL REFERENCES platform_github_bindings(sequence),
     github_id TEXT NOT NULL,
     expires_at INTEGER NOT NULL
   ) STRICT;
